// --- Constant Folding (CF) ---
static const int WIDTH = 20;
static const int HEIGHT = 3;

// CF: Compiler calculates (20 * 3) = 60
const int TOTAL = WIDTH * HEIGHT;

// --- Algebraic Rearrangement ---
int Input_X = runtime_read();

// Associativity/CF: (X + 100) - 20 -> X + 80
int Result_A = (Input_X + 100) - 20;

// Commutativity/CF: (X * 4) / 2 -> X * 2 (or X << 1)
int Result_B = (Input_X * 4) / 2;

// Identity Elimination: X * 1 + 0 -> X
int Result_C = Input_X * 1 + 0;

// Distributive Folding (Context dependent):
int Cost = Input_X * 5 + Input_X * 10; // Optimized to Input_X * 15
